<?php /** @var array $privacy @var array $requests @var \Core\Security\Csrf $csrf @var string $basePath */
$counts = array_count_values(array_column($requests, 'status')); $open = (int) ($counts['new'] ?? 0) + (int) ($counts['verified'] ?? 0);
?>
<section class="status-strip"><div class="status-chip <?= $privacy['banner_enabled'] ? 'ok' : 'warn' ?>"><strong><?= $privacy['banner_enabled'] ? 'On' : 'Off' ?></strong><span>Consent choices</span></div><div class="status-chip <?= $privacy['first_party_enabled']?'ok':'warn' ?>"><strong><?= $privacy['first_party_enabled']?'On':'Paused' ?></strong><span>First-party analytics</span></div><div class="status-chip"><strong><?= e(strtoupper($privacy['provider'])) ?></strong><span>Optional provider</span></div><div class="status-chip <?= $open ? 'warn' : 'ok' ?>"><strong><?= $open ?></strong><span>Open requests</span></div></section>
<section class="card"><div class="card-heading"><div><p class="section-kicker">Visitor consent</p><h2>Optional third-party analytics</h2><p class="card-subtitle">Google Analytics or Plausible only loads after explicit visitor permission. Core’s anonymous first-party reports are managed separately in Analytics and honor DNT/GPC.</p></div><div class="button-row"><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/analytics">Open first-party analytics</a><a class="btn secondary" href="<?= e_attr($basePath) ?>/privacy/request" target="_blank" rel="noopener">Open privacy center ↗</a></div></div><form method="post" data-protect-unsaved><?= $csrf->field() ?><input type="hidden" name="action" value="settings"><input type="hidden" name="banner_enabled" value="0"><label class="toggle-control"><span><strong>Show privacy choices</strong><small>Required when an optional third-party analytics provider is configured.</small></span><input type="checkbox" name="banner_enabled" value="1" <?= $privacy['banner_enabled'] ? 'checked' : '' ?>><span class="toggle-track" aria-hidden="true"></span></label><div class="privacy-settings-grid"><div><label for="privacy-provider">Optional provider</label><select id="privacy-provider" name="provider" data-toggle-target="#privacy-site-id" data-toggle-not-value="none"><?php foreach (['none' => 'None', 'ga4' => 'Google Analytics 4', 'plausible' => 'Plausible'] as $value => $label): ?><option value="<?= e_attr($value) ?>" <?= $privacy['provider'] === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div data-dependent-group><label for="privacy-site-id">Measurement ID or domain</label><input id="privacy-site-id" name="site_id" value="<?= e_attr($privacy['site_id']) ?>" placeholder="G-XXXXXXXX or example.com"><small>Credentials and custom scripts are never accepted here.</small></div><button class="btn">Save privacy settings</button></div></form></section>

<section class="card"><div class="card-heading"><div><p class="section-kicker">Request workflow</p><h2>Privacy requests</h2><p class="card-subtitle">Verify identity first, perform the requested action, then record a concise resolution note.</p></div><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/privacy/export">Export evidence CSV</a></div><?php if (!$requests): ?><div class="empty-state"><strong>No privacy requests</strong><span>Requests submitted through the public privacy center will appear here.</span></div><?php else: ?><div class="privacy-request-list"><?php foreach ($requests as $item): ?><article class="privacy-request-card status-<?= e_attr($item['status']) ?>"><header><div><span class="badge neutral">#<?= (int) $item['id'] ?></span><span class="badge <?= $item['status'] === 'completed' ? 'ok' : ($item['status'] === 'verified' ? 'active' : 'warn') ?>"><?= e(ucfirst($item['status'])) ?></span></div><time><?= e($item['created_at']) ?></time></header><div class="privacy-request-main"><div><p class="section-kicker"><?= e($item['request_type']) ?> request</p><h3><?= e($item['email']) ?></h3><p><?= nl2br(e((string) ($item['details'] ?: 'No additional details supplied.'))) ?></p></div><dl><div><dt>Received</dt><dd><?= e($item['created_at']) ?></dd></div><div><dt>Verified</dt><dd><?= e($item['verified_at'] ?? 'Not yet') ?></dd></div><div><dt>Completed</dt><dd><?= e($item['completed_at'] ?? 'Not yet') ?></dd></div></dl></div><?php if (!empty($item['resolution_note'])): ?><div class="resolution-note"><strong>Resolution evidence</strong><p><?= nl2br(e($item['resolution_note'])) ?></p></div><?php endif; ?><footer><?php if ($item['status'] === 'new'): ?><form method="post" data-confirm="Confirm you verified this requester’s identity outside Website Core?"><?= $csrf->field() ?><input type="hidden" name="action" value="verify"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><button class="btn small">Record identity verification</button></form><?php elseif ($item['status'] === 'verified'): ?><form method="post" class="privacy-resolution-form"><?= $csrf->field() ?><input type="hidden" name="action" value="complete"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><label for="resolution-<?= (int) $item['id'] ?>">Resolution note</label><input id="resolution-<?= (int) $item['id'] ?>" name="resolution_note" maxlength="2000" required placeholder="What was provided, corrected, or deleted?"><button class="btn small" data-confirm="Complete this request with the recorded resolution evidence?">Complete request</button></form><?php else: ?><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="reopen"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><button class="btn small secondary" data-confirm="Reopen this completed request for follow-up?">Reopen</button></form><?php endif; ?></footer></article><?php endforeach; ?></div><?php endif; ?></section>
